def solve():
    N, M = map(int, input().split())

    # Build adjacency list for stronger relationships
    # stronger[x] contains set of people that person x is stronger than
    stronger = [set() for _ in range(N + 1)]

    # Read the given information
    for _ in range(M):
        a, b = map(int, input().split())
        stronger[a].add(b)

    # Apply transitivity using Floyd-Warshall style approach
    # For each person, propagate their relationships
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            if k in stronger[i]:
                # Person i is stronger than person k
                # Person k is stronger than people in stronger[k]
                # So person i is stronger than people in stronger[k]
                for j in stronger[k]:
                    stronger[i].add(j)

    # Now find candidates for strongest programmer
    # Person x is strongest if:
    # 1. Person x is stronger than all others (len(stronger[x]) == N-1)
    # 2. No one is stronger than person x (no one has x in their stronger set)

    candidates = []

    for person in range(1, N + 1):
        # Check if person is stronger than everyone else
        if len(stronger[person]) == N - 1:
            # Check if no one is stronger than this person
            is_strongest = True
            for i in range(1, N + 1):
                if i != person and person in stronger[i]:
                    is_strongest = False
                    break
            if is_strongest:
                candidates.append(person)

    # If exactly one candidate, return it
    # Otherwise return -1
    if len(candidates) == 1:
        print(candidates[0])
    else:
        print(-1)

